{
  "references": [
    {
      "id": "R1",
      "summary_ko": "그녀가 일어서서가 아니라 점프할 때 머리를 부딪힘."
    },
    {
      "id": "R2",
      "summary_ko": "그녀가 상자 위에 양발로 서 있음."
    },
    {
      "id": "R3",
      "summary_ko": "벽에 걸린 머리 장식은 곰이 아니라 사자나 큰 고양이과 동물의 머리처럼 보임."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "점프하는 동안 머리와 상반신이 벽걸이 장식 안으로 겹쳐져 들어감(블렌딩됨)."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "점프 중 머리를 부딪히는 현상과 벽 장식에 머리 및 상반신이 겹쳐지는 물리적 관통/블렌딩 현상이 동일한 충돌 결함인지 설명이 상이하여 일치 여부가 불확실함."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "상자 위에 서 있는 발의 위치에 관한 내용과 점프 중 벽 장식과 겹치는 현상은 서로 다른 대상 및 결함을 다룸."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "벽에 걸린 동물 머리 장식의 종류에 대한 설명과 사람이 점프하며 벽 장식과 겹쳐지는 물리적 결함은 다른 현상임."
    }
  ]
}
